mapper.select:
select  from content_draft
where owner_member_id = #{ownerMemberId}
  and business_type = #{businessType}
  and client_draft_key = #{clientDraftKey}

mapper.update:
update content_draft
set subject_id = #{draft.subjectId}, payload_json = #{draft.payloadJson},
    payload_hash = #{draft.payloadHash}, updated_by_device = #{draft.updatedByDevice},
    version = version + 1, update_time = now(3)
where id = #{draft.id} and owner_member_id = #{draft.ownerMemberId}
  and status = 'DRAFT' and version = #{expectedVersion}

update content_draft
set status = 'DELETED', version = version + 1, update_time = now(3)
where id = #{id} and owner_member_id = #{ownerMemberId}
  and status = 'DRAFT' and version = #{expectedVersion}

update content_draft
set status = 'PUBLISHED', published_resource_id = #{publishedResourceId},
    version = version + 1, update_time = now(3)
where id = #{id} and owner_member_id = #{ownerMemberId}
  and status = 'DRAFT' and version = #{expectedVersion}
